// Park every unit far away so it cannot see the player.
function banish(mgr, x = 400, z = 400) {
  mgr.units.forEach((u, i) => {
    u.car.x = x + i * 30; u.car.z = z + i * 30;
    u.state = 'PATROL'; u.waypoints = []; u.wpIndex = 0;
  });
}

